INSERT INTO events (dynasty_id, year, year_end, lng, lat, short, title, detail, impact, place, category) VALUES
  ('song', 976, 980, 112.94, 28.23, '岳麓书院', '岳麓书院创建', '开宝九年，潭州太守朱洞在岳麓山创建书院。大中祥符八年真宗召见山长周式，嘉其办学有成，亲书岳麓书院匾额赐之，并赠内府经书，书院自此闻达天下。', '岳麓书院为宋初四大书院之一，弦歌千年不绝。朱熹、张栻后来此会讲，开书院讲会制度之先声，湖湘学派亦由此发源。', '岳麓山（今长沙）', 'figure'),
  ('song', 978, 978, 120.16, 30.25, '吴越纳土', '吴越纳土 · 和平归宋', '太平兴国三年，吴越国王钱俶奉诏入朝，审时度势，上表献两浙十三州一军八十六县军民版籍，纳土归宋。江南最后的割据政权就此和平落幕，两浙全境免遭兵燹。', '钱氏以一姓之社稷，活万家之生灵，两浙经济得以持续繁荣。宋室厚待钱氏子孙，其族有宋一代人才辈出，为中国史上罕见的和平统一范例。', '杭州', 'era'),
  ('song', 979, 979, 116.35, 39.95, '高梁河之战', '高梁河之战 · 太宗伐辽', '宋太宗灭北汉后挟胜攻辽，亲率大军围幽州，攻城半月不克。辽将耶律沙等率援军驰至，与宋军大战于高梁河，宋军全线崩溃，太宗身中两箭，乘驴车南逃。', '收复燕云的最佳窗口就此关闭，宋辽攻守易势。太宗此后确立将从中御、守内虚外的方针，武将愈受猜防，北宋军力的进取性自此转衰。', '高梁河（今北京）', 'military'),
  ('song', 986, 986, 115.97, 39.48, '雍熙北伐', '雍熙北伐 · 岐沟关之败', '辽圣宗新立，宋太宗分东中西三路北伐。东路曹彬冒进涿州，粮尽回撤，在岐沟关被辽军铁骑追及，大败溃散。西路杨业奉命护民南迁，被监军所逼出战，陈家谷口援军已移，力战被俘，绝食三日而死。', '北宋最后一次战略进攻惨败收场，河北精锐尽丧，此后对辽终其一朝再无力主动出击。杨业殉国，边人痛惜，杨家将故事由此演绎千年。', '岐沟关（今河北涿州）', 'military'),
  ('song', 993, 995, 103.95, 30.98, '王小波起义', '王小波·李顺起义', '青城茶贩王小波聚众起义，宣言吾疾贫富不均，今为汝均之，从者云集。王小波中矢死后，妻弟李顺继起，攻占成都，建大蜀政权，年号应运。宋廷调重兵入川镇压，起义至至道初年失败。', '中国历史上首次鲜明提出均贫富纲领的农民起义。宋廷此后宽减蜀赋、慎择守令，川峡社会渐安，三十年后交子亦在成都应运而生。', '青城·成都', 'economy'),
  ('song', 997, 1003, 114.35, 34.78, '真宗即位', '真宗即位 · 咸平之治', '太宗崩，太子赵恒即位，是为真宗。即位之初分天下为十五路，各置转运使总揽财赋。真宗勤于听政，蠲免五代积欠，劝课农桑，户口垦田大增，史称咸平之治。', '承太祖太宗之成而臻小康，北宋人口与垦田稳步增长。然澶渊定盟后真宗渐怠于政，晚年营宫观、信祥瑞，朝政日弛。', '汴京（今开封）', 'era'),
  ('song', 1008, 1013, 117.13, 36.19, '天书封禅', '天书封禅 · 真宗东封', '澶渊之盟后，真宗深以城下之盟为耻，王钦若遂倡封禅大功业之说。先有神人赐天书之梦，继而天书降于左承天门，遂改元大中祥符，东封泰山，又西祀汾阴，广修宫观，举国若狂。', '丁谓等借祥瑞固宠，玉清昭应宫之役靡费国帑无算。北宋财政自此渐困，士风浮诞，史家视为真宗朝由治趋衰的转折点。', '泰山（今山东泰安）', 'era'),
  ('song', 1009, 1016, 115.65, 34.41, '应天书院', '应天府书院赐额', '应天府民曹诚就戚同文讲学旧舍，出资三百万重建学舍一百五十间，聚书数千卷，延请名儒主持教导。真宗嘉叹，诏赐额应天府书院，由是闻名。范仲淹早年断齑画粥，苦读于此数载。', '应天书院跻身宋初四大书院，庆历间升为南京国子监，为宋代唯一升入国子监的书院。范仲淹苦读发迹于此，日后庆历兴学即种因于此。', '应天府（今商丘）', 'figure'),
  ('song', 1015, 1027, 114.35, 34.78, '汴河漕运', '汴河漕运 · 东京梦华', '大中祥符年间，汴河岁漕江淮米定额达七百万石，创历代之最。漕船自淮入汴直抵京师，供养东京百万军民。城坊墙尽撤，夜市连至三更，酒楼瓦舍遍布通衢，为当时世界最大都会。', '汴河成为北宋立国命脉，开封遂取代长安洛阳而为天下之都。以漕运供养京师的格局，也决定两宋国防始终受制于漕路安危。', '汴京（今开封）', 'economy'),
  ('song', 1023, 1033, 114.35, 34.78, '刘太后临朝', '刘太后临朝 · 政出宫闱', '真宗崩，仁宗十三岁即位，尊刘氏为皇太后。次年改元天圣，取二圣人共治之意，刘太后临朝称制十一年。她号令严明，裁抑宦官外戚，信用王曾、吕夷简等大臣，天下晏然。', '宋代太后称制而不乱的第一个范例，此后曹太后、高太后临朝皆循此故事。刘太后晚年几欲效武后故事而终守臣节，宋廷未生内祸。', '汴京（今开封）', 'era'),
  ('song', 1033, 1043, 114.35, 34.78, '仁宗亲政', '仁宗亲政 · 仁政致治', '刘太后崩，仁宗始亲政，改元景祐。仁宗恭俭仁恕，擢用台谏，与士大夫共治天下。范仲淹、韩琦、富弼、包拯、欧阳修皆出其朝，在位四十二年，号称人才极盛之世。', '嘉祐之治为北宋政治清明之极，唐宋八大家宋六人尽出仁宗一朝。仁宗崩，辽道宗握宋使之手而泣，谓四十二年不识兵革。', '汴京（今开封）', 'era'),
  ('song', 1040, 1040, 109.42, 36.72, '三川口之战', '三川口之战 · 西夏首胜', '元昊称帝后首度大举攻宋，围延州。鄜延路副总管刘平、石元孙率万余人驰援，行至三川口陷入重围，苦战两日，全军覆没，刘平被执而骂贼不屈。范仲淹、韩琦自此临危受命经略陕西。', '宋夏大规模战争正式爆发，宋军野战孱弱暴露无遗。朝廷自此改行深沟高垒、筑城练兵之策，西北战线方才稳住。', '三川口（今延安西北）', 'military'),
  ('song', 1040, 1043, 109.49, 36.60, '范仲淹戍边', '范仲淹自请戍边', '康定元年，范仲淹自请知延州。他改更戍旧法，分州兵为六将，量敌众寡更番出战，又大兴营田，命种世衡筑青涧城以据要害。西夏相戒曰，无以延州为意，小范老子胸中自有数万甲兵。', '范仲淹以守为攻，边防渐固，军中谣曰军中有一范，西贼闻之惊破胆。其屯田固守、恩信招抚之策成为宋夏相持的基石，戍边历练亦启日后新政。', '延州（今延安）', 'figure'),
  ('song', 1041, 1041, 106.12, 35.62, '好水川之战', '好水川之战 · 任福战殁', '元昊亲率大军佯败诱敌，设伏于好水川。任福率军追击入伏，宋军开夏人所弃泥盒，鸽自盒出盘旋其上，夏军四合围之，任福父子力战殉国，全军覆没，仅数百人溃归，关右大震。', '宋军再遭惨败，韩琦上章自劾。宋廷自知无力速胜，改行范仲淹坚壁清野、以老敌师之策，宋夏进入长期相持。', '好水川（今宁夏隆德）', 'military'),
  ('song', 1042, 1042, 106.20, 36.10, '定川寨之战', '定川寨之战 · 夏军深入', '元昊再度南侵，泾原路副都部署葛怀敏会兵御敌，行至定川寨被夏军断桥围困，寨中乏水，突围大溃，葛怀敏等九将战死。夏军乘胜长驱直抵渭州，焚荡六百里而还，关中震恐。', '宋军三败于西夏，被迫转而议和。庆历四年宋夏达成和议，夏主名义称臣，宋岁赐银七万两、绢十五万匹、茶三万斤，西北烽烟暂息。', '定川寨（今宁夏固原西北）', 'military'),
  ('song', 1044, 1045, 114.35, 34.78, '武经总要', '《武经总要》成书', '曾公亮、丁度奉敕编纂的兵学巨著《武经总要》奏上，凡四十卷。书中备载历代兵谋、阵法与攻守器械，并收录毒药烟球、蒺藜火球、火炮火药三种火药配方，硝磺配伍分明，可依方配制。', '火药自此由炼丹房进入制式军工，为世界现存最早的成文火药配方。宋军依方造火器用于城守，火器时代由此滥觞，后经战争与商路西传。', '汴京（今开封）', 'invention'),
  ('song', 1045, 1048, 120.16, 30.25, '毕昇活字', '毕昇发明活字', '庆历年间，布衣毕昇创胶泥活字。以胶泥刻字，薄如钱唇，火烧令坚。印时置铁板敷松脂蜡与纸灰，排字其上，持火炀之，药稍熔则以平板按平，一版刷印、一版排布，瞬息可成。其法赖沈括《梦溪笔谈》而传。', '书籍复制摆脱整版雕镌之费，是印刷术的划时代飞跃。活字法后东传高丽日本，西经丝路入欧，早于古登堡四百年，深刻改变世界文化传播。', '杭州', 'invention'),
  ('song', 1047, 1048, 115.84, 37.06, '王则之乱', '贝州王则之乱', '贝州宣毅军小校王则久以弥勒教结党军中，乘冬至祭天之夜起事，囚知州，据贝州城，被推为东平王，国号安阳，改元得圣。明镐久攻不克，文彦博新拜相，自请往讨，穴城而入，槛送王则于京师。', '历时六十六日的变乱震动河北，暴露军政腐败与民间秘密结社的巨大能量。文彦博以平乱声望益隆，其后出入将相五十年。', '贝州（今河北清河）', 'economy'),
  ('song', 1057, 1058, 114.35, 34.78, '嘉祐二年榜', '嘉祐二年榜 · 千古第一榜', '嘉祐二年贡举，欧阳修知贡举，痛抑险怪奇涩之文，天下文风为之一变。是榜人才之盛千古罕见：苏轼、苏辙、曾巩、曾布、程颢、张载同登进士第。欧阳修读苏轼谢启，有当避此人出一头地之叹。', '宋代古文运动与贡举文风就此定型，唐宋八大家中五人与此榜相关。这批士人日后主导熙宁变法与元祐更化，左右北宋中后期政局。', '汴京（今开封）', 'era'),
  ('song', 1060, 1062, 114.35, 34.78, '新唐书成书', '欧阳修《新唐书》成书', '嘉祐五年，欧阳修、宋祁奉敕合修的《新唐书》奏上，历十七年而成，共二百二十五卷。宋祁撰列传，欧阳修撰本纪、志、表，恢复立表之体，新创选举、兵二志，记唐代典章尤详。', '与《旧唐书》并行于世，志表详赡，为治唐史者所必资。宰相监修、馆阁分撰的成例，为金元两朝修前朝史所沿用。', '汴京（今开封）', 'figure'),
  ('song', 1067, 1069, 114.35, 34.78, '神宗即位', '神宗即位 · 锐意求治', '英宗崩，二十岁的神宗赵顼即位，慨然有雪数世之耻之志。他先向老臣富弼问边事，得到愿二十年口不言兵之戒，转而属意久负盛名的王安石，越次入对，君臣相得，变法由此发端。', '皇帝与士大夫共谋革新的格局确立，熙宁变法随之展开。神宗求治心切亦好用兵，北宋自此进入大变革与大党争交织的时代。', '汴京（今开封）', 'era'),
  ('song', 1070, 1077, 107.86, 34.26, '张载讲学', '张载横渠讲学', '张载与王安石论新法不合，遂退居凤翔郿县横渠镇，终日危坐一室，俯而读、仰而思，以六经告学者，教人知礼成性、变化气质。门人辑其言论为《经学理窟》，晚年著《正蒙》，学者称横渠先生。', '关学自此立宗。为天地立心，为生民立命，为往圣继绝学，为万世开太平的横渠四句，成为此后中国士人千年不易的精神纲领。', '横渠镇（今陕西眉县）', 'figure'),
  ('song', 1071, 1073, 115.98, 29.55, '濂溪讲学', '周敦颐濂溪讲学', '周敦颐晚年知南康军，筑书堂于庐山莲花峰下，用家乡濂溪之名名之，讲学著述其中。所著《太极图说》与《通书》，阐无极而太极、主静立人极之旨，开宋明理学之先河，二程兄弟皆尝从学。', '周敦颐被后世尊为理学开山，《太极图说》成为宋明理学的理论起点。濂溪之学经二程、朱熹发扬光大，蔚为八百年正统思想。', '庐山（今江西九江）', 'figure'),
  ('song', 1072, 1073, 103.86, 35.37, '熙河开边', '熙河开边 · 王韶拓地', '王韶上《平戎策》，言欲制西夏当先复河湟。熙宁五年他率军西进，一举收复熙州，次年下河州，洮、岷、叠、宕诸部相继归附，拓地两千余里，为北宋开国以来对外用兵的最大胜利。', '秦凤、熙河连片，西夏右臂受制，新党富国强兵之效大显。神宗大受鼓舞，进取灵夏之心愈炽，直接引出元丰伐夏之役。', '熙州（今甘肃临洮）', 'military'),
  ('song', 1072, 1085, 114.35, 34.78, '市易法', '市易法颁行', '熙宁五年颁市易法，设市易务于汴京。客旅滞销货物由官府平价收买，市面短缺时再行卖出，行铺小贩可以抵押赊贷于市易务，兼并之家不得乘急邀价，岁收息钱以充国用。', '官府平物价、抑兼并，国库岁入大增。然官吏强令抑配渐生苛扰，市易成为新法中最受争议的一项，元祐初随新法同罢。', '汴京（今开封）', 'economy'),
  ('song', 1080, 1085, 112.45, 34.62, '洛学兴起', '二程讲学洛阳', '元丰年间，程颢与弟程颐讲学洛阳，从游者日众。程颢尝言，吾学虽有所受，天理二字却是自家体贴出来。门下杨时、谢良佐、游酢皆为高弟，程门立雪即杨时、游酢侍立伊川门前的故事。', '洛学南传，杨时开闽学之绪，四传至朱熹而集其大成。天理与格物穷理之说，成为支配此后八百年东亚思想的主脉。', '洛阳', 'figure'),
  ('song', 1081, 1081, 106.34, 38.06, '五路伐夏', '元丰五路伐夏', '西夏梁太后幽禁惠宗，神宗以为有机可乘，发熙河、泾原、环庆、鄜延、河东五路大军会攻灵州。种谔先捷于米脂，刘昌祚前锋薄灵州城下，然诸帅各进失期，粮运复为夏军抄绝，天寒大雪，诸军相继溃归。', '倾国之师无功而返，诸路统帅互不统属之弊暴露无遗。此后对夏改取步步筑城蚕食之策，永乐城之筑即由此而起。', '灵州（今宁夏灵武）', 'military'),
  ('song', 1082, 1082, 110.15, 37.78, '永乐城之战', '永乐城之败', '徐禧力主筑永乐城以逼横山，城甫成，西夏倾国三十万众来攻，截断水源，昼夜急攻。城中凿井不得泉，士卒渴死者大半，城遂陷，徐禧、李舜举、高永能皆死，士卒役夫死者无算。神宗临朝恸哭，为之不食。', '元丰朝对夏用兵的最大挫败，神宗锐气尽挫，自此不复大举西讨。熙丰强兵之志实败于永乐城下，亦为日后元祐更化之伏笔。', '永乐城（今陕西米脂西）', 'military'),
  ('song', 1085, 1093, 114.35, 34.78, '元祐更化', '哲宗即位 · 元祐更化', '神宗崩，十岁的哲宗即位，太皇太后高氏垂帘主政，起用司马光、吕公著。数月之间，保甲、方田、市易诸法相继罢废，官制多复旧观，改元元祐，史称元祐更化。章惇、蔡确等新党相继出朝。', '新法尽废而吏病未除，党争自此由政见异同沦为恩怨倾轧。元祐更化与绍圣绍述循环报复，终为蔡京专权铺平道路。', '汴京（今开封）', 'era'),
  ('song', 1087, 1100, 118.58, 24.93, '泉州市舶司', '泉州设市舶司', '元祐二年，宋廷增设泉州市舶司，掌蕃商海舶的抽解博买。刺桐港自此蕃舶鳞集，城南蕃坊客商杂处，阿拉伯、波斯、南洋诸国商货毕至，贸易之盛渐与广州并列为全国两大港。', '泉州自此加速崛起，至南宋登顶，宋末元初遂成东方第一大港。市舶岁入成为宋朝财政的重要支柱，海上丝路臻于鼎盛。', '泉州', 'economy'),
  ('song', 1088, 1089, 119.42, 32.19, '梦溪笔谈', '沈括著《梦溪笔谈》', '沈括晚年退居润州梦溪园，尽平生见闻撰成《梦溪笔谈》。书中首记磁针能指南然常微偏东，为世界最早的磁偏角记录，又载毕昇活字、隙积术、会圆术与石油之名，并断言石油后必大行于世。', '李约瑟誉为中国科学史上的里程碑。磁偏角记载早于欧洲四百年，毕昇活字亦赖此书而传于后世，堪称宋代科技的百科全书。', '润州（今江苏镇江）', 'invention'),
  ('song', 1090, 1091, 120.15, 30.24, '疏浚西湖', '苏轼知杭州 · 疏浚西湖', '元祐四年，苏轼以龙图阁学士知杭州。次年见西湖葑草湮塞过半，奏请浚湖，募民采葑掘泥，筑长堤横贯湖南北，置六桥以通舟楫，植芙蓉杨柳其上，杭人号为苏公堤。又新浚六井，设病坊济民。', '苏堤春晓至今居西湖十景之首，西湖景观格局由此奠定。苏轼两仕杭州，遗爱在民，杭州从此成为东坡文化记忆最深的都会。', '杭州', 'figure'),
  ('song', 1092, 1093, 114.35, 34.78, '水运仪象台', '苏颂水运仪象台', '元祐七年，苏颂与韩公廉建成水运仪象台。台高逾三丈，上设浑仪以测天，中悬浑象以象天，下置司辰木人报时，以水力激轮运转。其枢轮杠杆擒纵之制，为后世钟表擒纵器的先声，苏颂又撰《新仪象法要》记之。', '集观测、演示、报时于一体的世界首座天文钟。李约瑟称其擒纵机构或为欧洲中世纪天文钟的直接祖先，世界机械史上意义深远。', '汴京（今开封）', 'invention'),
  ('song', 1094, 1098, 114.35, 34.78, '绍圣绍述', '绍圣绍述 · 新党复位', '高太后崩，哲宗亲政，改元绍圣，以绍述先志为名复行免役诸法，起用章惇、曾布、蔡卞等新党。元祐旧臣被指为挟奸罔上，贬窜岭南，苏轼再谪惠州、儋州，朝堂几乎为之一空。', '绍述名为恢复新法，实多意气报复。新旧党仇愈结愈深，崇宁党禁与蔡京擅权，皆由此一路演进而来。', '汴京（今开封）', 'era'),
  ('song', 1102, 1106, 114.35, 34.78, '崇宁新政', '崇宁新政 · 元祐党禁', '徽宗任蔡京为相，托绍述之名行聚敛之实。定元祐党籍，御书刻石端礼门，后扩至三百零九人颁之天下，禁锢其子孙，并禁元祐学术。又铸当五大钱，行三舍法于州县，以图尽复新法之盛。', '党禁尽逐异己，蔡京由此独相擅权二十余年。当五大钱滥铸致钱法大乱，物价腾踊，北宋统治危机全面加深。', '汴京（今开封）', 'era'),
  ('song', 1119, 1121, 113.26, 23.13, '指南针航海', '指南针用于航海', '朱彧《萍洲可谈》记广州蕃舶舟师之能：夜则观星，昼则观日，阴晦观指南针。此为世界现存最早的罗盘航海记录。海员并以针盘测定航线，编为针路簿，指南针自此成为远洋海船的标准配置。', '中国航海率先进入罗盘导航时代，为宋元海上丝路的鼎盛与远洋贸易提供关键技术，后经阿拉伯人传入欧洲，助推大航海时代。', '广州', 'invention'),
  ('song', 1120, 1121, 118.84, 29.61, '方腊起义', '方腊起义 · 东南震动', '睦州青溪帮源峒漆园主方腊，不堪造作局苛取与花石纲之扰，借摩尼教聚众起事，以诛朱勔为名，旬月间连陷睦、歙、衢、杭等六州五十二县，东南大震。徽宗罢花石纲，遣童贯率十五万禁军南下，次年方腊被擒。', '起义截断朝廷东南财赋命脉，镇压耗尽禁军精锐，北宋外强中干尽露于金人眼底。花石纲之弊虽稍敛，国势已不可复支。', '青溪（今浙江淳安）', 'economy'),
  ('song', 1122, 1124, 114.35, 34.78, '清明上河图', '张择端《清明上河图》', '东武人张择端供职图画院，绘成长卷《清明上河图》。绢本设色，纵二十四点八厘米，横逾五米，写汴京汴河两岸的舟桥市肆、酒楼茶坊，人物数百而神态各异，街衢屋宇纤悉具备，东京繁华尽收一卷。', '北宋城市经济与市民生活的第一手图像史料，中国古代风俗画的巅峰之作。今日研究者仍奉为宋代社会的纸上百科。', '汴京（今开封）', 'figure'),
  ('song', 1123, 1123, 116.42, 39.90, '燕云交割', '燕京交割 · 燕山府设立', '金依海上之盟以燕京及涿、易、檀、顺、景、蓟六州归宋，宋于原许岁币外另增代租钱一百万贯。宋改燕京为燕山府，置燕山府路。金人尽驱燕地人口财货北去，宋所得者残破几为空城。', '朝廷引为大功，实启大祸。旋有平州张觉纳降事件，授金以南侵口实，新得之燕山转瞬沦为战场，边防危如累卵。', '燕京（今北京）', 'military'),
  ('song', 1126, 1126, 114.35, 34.78, '东京保卫战', '东京保卫战 · 李纲守城', '靖康元年正月，金军渡河直抵汴京城下。李纲临危受任亲征行营使，登城督战，以炮石檑木却敌，金军攻城不克。勤王之师四集，金人敛兵议和北退。同年冬金军再度合围，闰十一月汴京城破。', '首次守城成功本可转为生机，朝廷却斥李纲、罢战备，复信郭京六甲神兵开城御敌，汴京遂陷，靖康之祸终不可免。', '汴京（今开封）', 'military')
