-- 北宋历史事件 seed（P1 内容加深 · 第二批）
-- 与 01-song-events.sql 同格式；upsert 按 (dynasty_id, year, short) 身份，重复启动幂等。
-- 选题：军事 10 / era 10 / economy 6 / figure 9 / invention 5，共 40 条，年份均取 [960, 1126]。

ON CONFLICT(dynasty_id, year, short) DO UPDATE SET
  year_end = excluded.year_end,
  lng = excluded.lng,
  lat = excluded.lat,
  title = excluded.title,
  detail = excluded.detail,
  impact = excluded.impact,
  place = excluded.place,
  category = excluded.category
;
